{"command":"cd /workspace && cat > internal/lint/lint.go <<'EOF'
// Package lint contains the core abstractions shared by the linter
// driver and all the individual checkers.
package lint

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"sort"
	"strconv"
	"strings"
)

// Param describes a single configurable checker parameter.
type Param struct {
	Name    string
	Default interface{}
	Usage   string
}

// CheckerInfo holds the static metadata of a checker.
type CheckerInfo struct {
	Name    string
	Tags    []string
	Params  []Param
	Summary string
	Details string
	Before  string
	After   string
	Note    string

	// New creates a checker instance bound to the given context.
	New func(ctx *Context) (FileChecker, error)
}

// HasTag reports whether the checker is marked with the given tag.
func (info *CheckerInfo) HasTag(tag string) bool {
	for _, t := range info.Tags {
		if t == tag {
			return true
		}
	}
	return false
}

// Warning is a single linter diagnostic.
type Warning struct {
	Pos  token.Pos
	Text string
}

// FileChecker is implemented by every checker; it is invoked once per
// source file and returns the collected warnings.
type FileChecker interface {
	CheckFile(f *ast.File) []Warning
}

// GoVersion is a parsed "major.minor" Go release.
type GoVersion struct {
	Major int
	Minor int
}

// GreaterOrEqual reports whether v >= other. A zero version means "latest"
// and therefore satisfies every comparison.
func (v GoVersion) GreaterOrEqual(major, minor int) bool {
	if v.Major == 0 && v.Minor == 0 {
		return true
	}
	if v.Major != major {
		return v.Major > major
	}
	return v.Minor >= minor
}

// ParseGoVersion parses strings like "1.18" or "go1.18".
func ParseGoVersion(s string) (GoVersion, error) {
	var v GoVersion
	if s == "" {
		return v, nil
	}
	s = strings.TrimPrefix(s, "go")
	parts := strings.Split(s, ".")
	if len(parts) != 2 {
		return v, fmt.Errorf("invalid Go version format: %s", s)
	}
	major, err := strconv.Atoi(parts[0])
	if err != nil {
		return v, fmt.Errorf("invalid major version part: %s: %v", parts[0], err)
	}
	minor, err := strconv.Atoi(parts[1])
	if err != nil {
		return v, fmt.Errorf("invalid minor version part: %s: %v", parts[1], err)
	}
	v.Major = major
	v.Minor = minor
	return v, nil
}

// Params is a per-checker parameter set.
type Params map[string]interface{}

// Int returns the integer parameter value.
func (p Params) Int(name string) int {
	switch v := p[name].(type) {
	case int:
		return v
	case *int:
		return *v
	}
	panic(fmt.Sprintf("%s is not an int param", name))
}

// Bool returns the boolean parameter value.
func (p Params) Bool(name string) bool {
	switch v := p[name].(type) {
	case bool:
		return v
	case *bool:
		return *v
	}
	panic(fmt.Sprintf("%s is not a bool param", name))
}

// String returns the string parameter value.
func (p Params) String(name string) string {
	switch v := p[name].(type) {
	case string:
		return v
	case *string:
		return *v
	}
	panic(fmt.Sprintf("%s is not a string param", name))
}

// Context carries all the information about the program being checked
// that is shared between the checkers.
type Context struct {
	Fset      *token.FileSet
	Pkg       *types.Package
	TypesInfo *types.Info
	Sizes     types.Sizes
	Filename  string
	GoVersion GoVersion

	// Params holds the parameters of the checker currently being built.
	Params Params

	// Checker is the info of the checker currently being built.
	Checker *CheckerInfo
}

// NewContext creates an empty context.
func NewContext(fset *token.FileSet, sizes types.Sizes) *Context {
	return &Context{
		Fset:  fset,
		Sizes: sizes,
		TypesInfo: &types.Info{
			Types: map[ast.Expr]types.TypeAndValue{},
		},
	}
}

// SetPackage updates the package-level information.
func (ctx *Context) SetPackage(pkg *types.Package, info *types.Info) {
	ctx.Pkg = pkg
	ctx.TypesInfo = info
}

// SetFile updates the current file information.
func (ctx *Context) SetFile(filename string) {
	ctx.Filename = filename
}

// TypeOf returns the type of the expression or types.Typ[types.Invalid]
// when the information is unavailable.
func (ctx *Context) TypeOf(x ast.Expr) types.Type {
	if t := ctx.TypesInfo.TypeOf(x); t != nil {
		return t
	}
	return types.Typ[types.Invalid]
}

// SizeOf returns the size of the type in bytes.
func (ctx *Context) SizeOf(typ types.Type) (int64, bool) {
	defer func() { _ = recover() }()
	return ctx.Sizes.Sizeof(typ), true
}

var registry = map[string]*CheckerInfo{}

// RegisterInfo stores the checker documentation. A later call to
// RegisterChecker binds the implementation.
func RegisterInfo(info *CheckerInfo) {
	if _, ok := registry[info.Name]; ok {
		panic("duplicate checker info: " + info.Name)
	}
	registry[info.Name] = info
}

// RegisterChecker attaches the constructor to a previously registered info.
func RegisterChecker(name string, newFn func(ctx *Context) (FileChecker, error)) {
	info, ok := registry[name]
	if !ok {
		panic("checker info not registered: " + name)
	}
	if info.New != nil {
		panic("duplicate checker: " + name)
	}
	info.New = newFn
}

// GetCheckersInfo returns all registered checkers sorted by name.
func GetCheckersInfo() []*CheckerInfo {
	list := make([]*CheckerInfo, 0, len(registry))
	for _, info := range registry {
		list = append(list, info)
	}
	sort.Slice(list, func(i, j int) bool {
		return list[i].Name < list[j].Name
	})
	return list
}

// GetCheckerInfo returns a checker by name.
func GetCheckerInfo(name string) *CheckerInfo {
	return registry[name]
}
EOF
echo ok"}

