package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/build"
	"go/token"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"runtime"
	"runtime/pprof"
	"sort"
	"strings"
	"sync"

	"gocritic/internal/lint"
	"gocritic/internal/loader"
)

type checkerParamFlag struct {
	info *lint.CheckerInfo
	name string
	ptr  interface{}
}

type checkProgram struct {
	fs *flag.FlagSet

	targets []string

	checkGenerated     bool
	checkTests         bool
	concurrency        int
	cpuProfile         string
	memProfile         string
	disable            string
	enable             string
	enableAll          bool
	exitCode           int
	goVersion          string
	shorterErrLocation bool
	verbose            bool

	paramFlags []checkerParamFlag

	ctx      *lint.Context
	checkers []*boundChecker
	packages []*loader.Package

	cwd    string
	goroot string
	gopath string

	foundIssues bool
}

type boundChecker struct {
	info    *lint.CheckerInfo
	checker lint.FileChecker
}

var generatedFileRE = regexp.MustCompile(`Code generated .* DO NOT EDIT\.`)

func runCheck(args []string) {
	p := &checkProgram{}
	p.bindFlags()
	if err := p.fs.Parse(args); err != nil {
		log.Fatalf("parse args: %v", err)
	}
	p.targets = p.fs.Args()

	if p.cpuProfile != "" {
		f, err := os.Create(p.cpuProfile)
		if err != nil {
			log.Fatalf("create CPU profile: %v", err)
		}
		if err := pprof.StartCPUProfile(f); err != nil {
			log.Fatalf("start CPU profile: %v", err)
		}
		defer pprof.StopCPUProfile()
	}

	if err := p.initCheckers(); err != nil {
		log.Fatalf("init checkers: %v", err)
	}
	if err := p.loadProgram(); err != nil {
		// Loading failures are not fatal: nothing to check.
		return
	}
	p.runCheckers()

	if p.memProfile != "" {
		f, err := os.Create(p.memProfile)
		if err != nil {
			log.Fatalf("create memory profile: %v", err)
		}
		runtime.GC()
		if err := pprof.WriteHeapProfile(f); err != nil {
			log.Fatalf("write memory profile: %v", err)
		}
		f.Close()
	}

	if p.foundIssues {
		if p.cpuProfile != "" {
			pprof.StopCPUProfile()
		}
		os.Exit(p.exitCode)
	}
}

func defaultEnabledCheckers() string {
	var names []string
	for _, info := range lint.GetCheckersInfo() {
		if info.HasTag("experimental") || info.HasTag("opinionated") || info.HasTag("performance") || info.HasTag("security") {
			continue
		}
		names = append(names, info.Name)
	}
	return strings.Join(names, ",")
}

func (p *checkProgram) bindFlags() {
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	p.fs = fs

	for _, info := range lint.GetCheckersInfo() {
		for _, param := range info.Params {
			flagName := fmt.Sprintf("@%s.%s", info.Name, param.Name)
			pf := checkerParamFlag{info: info, name: param.Name}
			switch v := param.Default.(type) {
			case int:
				pf.ptr = fs.Int(flagName, v, param.Usage)
			case bool:
				pf.ptr = fs.Bool(flagName, v, param.Usage)
			case string:
				pf.ptr = fs.String(flagName, v, param.Usage)
			default:
				panic(fmt.Sprintf("unexpected param type %T", v))
			}
			p.paramFlags = append(p.paramFlags, pf)
		}
	}

	fs.BoolVar(&p.checkGenerated, "checkGenerated", false, "whether to check generated files")
	fs.BoolVar(&p.checkTests, "checkTests", true, "whether to check test files")
	fs.IntVar(&p.concurrency, "concurrency", runtime.GOMAXPROCS(0), "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	fs.StringVar(&p.cpuProfile, "cpuprofile", "", "write CPU profile to the specified file")
	fs.StringVar(&p.disable, "disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	fs.StringVar(&p.enable, "enable", defaultEnabledCheckers(), "comma-separated list of enabled checkers. Can include #tags")
	fs.BoolVar(&p.enableAll, "enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	fs.IntVar(&p.exitCode, "exitCode", 1, "exit code to be used when lint issues are found")
	fs.StringVar(&p.goVersion, "go", "", "select the Go version to target. Leave as string for the latest")
	fs.StringVar(&p.memProfile, "memprofile", "", "write memory profile to the specified file")
	fs.BoolVar(&p.shorterErrLocation, "shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
	fs.BoolVar(&p.verbose, "v", false, "whether to print output useful during linter debugging")
}

func (p *checkProgram) debugf(format string, args ...interface{}) {
