func splitList(s string) []string {
	var list []string
	for _, part := range strings.Split(s, ",") {
		if part != "" {
			list = append(list, part)
		}
	}
	return list
}

func (p *checkProgram) initCheckers() error {
	enabledByName := map[string]bool{}
	enabledTags := map[string]bool{}
	disabledByName := map[string]bool{}
	disabledTags := map[string]bool{}

	if !p.enableAll {
		for _, s := range splitList(p.enable) {
			if strings.HasPrefix(s, "#") {
				enabledTags[s[1:]] = true
			} else {
				enabledByName[s] = true
			}
		}
	}
	for _, s := range splitList(p.disable) {
		if strings.HasPrefix(s, "#") {
			disabledTags[s[1:]] = true
		} else {
			disabledByName[s] = true
		}
	}

	isEnabled := func(info *lint.CheckerInfo) bool {
		if p.enableAll {
			return true
		}
		if enabledByName[info.Name] {
			return true
		}
		for _, tag := range info.Tags {
			if enabledTags[tag] {
				return true
			}
		}
		return false
	}

	var selected []*lint.CheckerInfo
	for _, info := range lint.GetCheckersInfo() {
		if !isEnabled(info) {
			p.debugf("%s: not enabled by name or tag (-enable)", info.Name)
			continue
		}
		if disabledByName[info.Name] {
			p.debugf("%s: disabled by name (-disable)", info.Name)
			continue
		}
		disabledTag := ""
		for _, tag := range info.Tags {
			if disabledTags[tag] {
				disabledTag = tag
				break
			}
		}
		if disabledTag != "" {
			p.debugf("%s: disabled by %q tag (-disable)", info.Name, disabledTag)
			continue
		}
		selected = append(selected, info)
	}

	if len(selected) == 0 {
		return fmt.Errorf("empty checkers set selected")
	}

	p.ctx = lint.NewContext(token.NewFileSet(), nil)
	for _, info := range selected {
		params := lint.Params{}
		for _, pf := range p.paramFlags {
			if pf.info != info {
				continue
			}
			switch v := pf.ptr.(type) {
			case *int:
				params[pf.name] = *v
			case *bool:
				params[pf.name] = *v
			case *string:
				params[pf.name] = *v
			}
		}
		p.ctx.Params = params
		p.ctx.Checker = info
		c, err := info.New(p.ctx)
		if err != nil {
			p.debugf("%s: initialization failure: %v", info.Name, err)
			return err
		}
		p.checkers = append(p.checkers, &boundChecker{info: info, checker: c})
	}
	p.ctx.Params = nil
	p.ctx.Checker = nil

	for _, c := range p.checkers {
		p.debugf("%s is enabled", c.info.Name)
	}
	return nil
}

